if GZ and OB(5)==-777 then
local Ez=pcall(aV,OB)
yJ=(Ez and OB(5)==5)
if not yJ then pcall(aV,OB) sb.math.abs=(type(Yz)=="function" and Yz) or function(v) if v<0 then return -v end return v end end
end
end
end
if yJ then
local yp={md,YP,aV}
local IT=sb.string
if type(IT)=="table" then
yp[#yp+1]=IT.char yp[#yp+1]=IT.byte yp[#yp+1]=IT.sub yp[#yp+1]=IT.rep yp[#yp+1]=IT.len
end
if type(sb.table)=="table" and sb.table.concat then yp[#yp+1]=sb.table.concat end
