if type(sb.math)=="table" and sb.math.floor then yp[#yp+1]=sb.math.floor end
for eZ=1,#yp do local zt=yp[eZ] if type(zt)=="function" then pcall(aV,zt) end end
end
end
end
if not on then return nil end

